namespace expr {

class ExprContext {
public:
    std::map<std::string, std::string> variables;
    std::map<std::string, std::function<std::string(const std::string&)>> functions;

    ExprContext() {
        functions["upper"] = [](const std::string& s) {
            std::string r = s;
            std::transform(r.begin(), r.end(), r.begin(), ::toupper);
            return r;
        };
        functions["lower"] = [](const std::string& s) {
            std::string r = s;
            std::transform(r.begin(), r.end(), r.begin(), ::tolower);
            return r;
        };
        functions["len"] = [](const std::string& s) {
            return std::to_string(s.size());
        };
    }
};

class ExprEngine {
private:
    ExprContext& ctx_;
    static const std::regex expr_pattern_;

    std::string resolve_variable(const std::string& name) {
        auto it = ctx_.variables.find(name);
        if (it != ctx_.variables.end()) return it->second;
        return "";
    }

    std::string resolve_function(const std::string& fname, const std::string& arg) {
        auto it = ctx_.functions.find(fname);
        if (it != ctx_.functions.end()) return it->second(arg);
        return "";
    }

public:
    ExprEngine(ExprContext& ctx) : ctx_(ctx) {}

    std::string evaluate(const std::string& tmpl) {
        std::string result = tmpl;
        std::smatch match;
        while (std::regex_search(result, match, expr_pattern_)) {
            std::string expr = match[1].str();
            std::string replacement;
            size_t paren = expr.find('(');
            if (paren != std::string::npos && expr.back() == ')') {
                std::string fname = expr.substr(0, paren);
                std::string arg = expr.substr(paren + 1, expr.size() - paren - 2);
                std::string resolved_arg = resolve_variable(arg);
                if (resolved_arg.empty()) resolved_arg = arg;
                replacement = resolve_function(fname, resolved_arg);
            } else {
                replacement = resolve_variable(expr);
            }
            result = match.prefix().str() + replacement + match.suffix().str();
        }
        return result;
    }
};

const std::regex ExprEngine::expr_pattern_(R"(\$\{([^}]+)\})");

} // namespace expr

class RequestContext {
public:
    std::string method;
    std::string path;
    std::map<std::string, std::string> headers;
    std::map<std::string, std::string> query_params;
    std::string body;
};

class ResponseTemplate {
private:
    std::string template_str_;
    expr::ExprContext ctx_;
    std::mutex mtx_;

    static const std::vector<std::string> allowed_vars_;

    bool is_safe_value(const std::string& val) {
        // Block direct expression injection in values
        if (val.find("${") != std::string::npos) return false;
        return true;
    }

public:
    ResponseTemplate(const std::string& tmpl) : template_str_(tmpl) {}

    void bind_request(const RequestContext& req) {
        std::lock_guard<std::mutex> lock(mtx_);
        for (const auto& param : req.query_params) {
            if (is_safe_value(param.second)) {
                ctx_.variables["param." + param.first] = param.second;
            }
        }
        ctx_.variables["request.method"] = req.method;
        ctx_.variables["request.path"] = req.path;
    }

    void bind_data(const std::string& key, const std::string& value) {
        std::lock_guard<std::mutex> lock(mtx_);
        ctx_.variables[key] = value;
    }

    std::string render() {
        std::lock_guard<std::mutex> lock(mtx_);
        expr::ExprEngine engine(ctx_);
        return engine.evaluate(template_str_);
    }
};

const std::vector<std::string> ResponseTemplate::allowed_vars_ = {
    "param.", "request.", "data."
};

class AsyncHandler {
private:
    std::string greeting_template_;

    std::string sanitize_for_display(const std::string& input) {
        std::string result;
        for (char c : input) {
            switch (c) {
                case '<': result += "&lt;"; break;
                case '>': result += "&gt;"; break;
                case '&': result += "&amp;"; break;
                case '"': result += "&quot;"; break;
                default: result += c;
            }
        }
        return result;
    }

public:
    AsyncHandler() : greeting_template_("Hello, ${upper(param.name)}! Welcome to ${request.path}") {}

    std::future<std::string> handle_greeting(const RequestContext& req) {
        return std::async(std::launch::async, [this, req]() -> std::string {
            ResponseTemplate resp(greeting_template_);
            resp.bind_request(req);
            return resp.render();
        });
    }

    std::future<std::string> handle_echo(const RequestContext& req) {
        return std::async(std::launch::async, [this, req]() -> std::string {
            auto it = req.query_params.find("msg");
            if (it == req.query_params.end()) return "No message provided";

            std::string user_msg = sanitize_for_display(it->second);

            // Build template dynamically with user content as template variable reference
            std::string tmpl = "Echo: ${data.message}";
            ResponseTemplate resp(tmpl);
            resp.bind_request(req);
            resp.bind_data("data.message", user_msg);
            return resp.render();
        });
    }

    std::future<std::string> handle_profile(const RequestContext& req) {
        return std::async(std::launch::async, [this, req]() -> std::string {
            auto name_it = req.query_params.find("name");
            auto fmt_it = req.query_params.find("format");

            std::string name = (name_it != req.query_params.end()) ? name_it->second : "Guest";
            std::string fmt = (fmt_it != req.query_params.end()) ? fmt_it->second : "plain";

            // Format determines the template structure
            std::string tmpl;
            if (fmt == "decorated") {
                tmpl = "*** ${param.name} ***";
            } else if (fmt == "upper") {
                tmpl = "${upper(param.name)}";
            } else {
                tmpl = "${param.name}";
            }

            ResponseTemplate resp(tmpl);
            resp.bind_request(req);
            return resp.render();
        });
    }

    std::future<std::string> handle_custom_template(const RequestContext& req) {
        return std::async(std::launch::async, [this, req]() -> std::string {
            auto tmpl_it = req.query_params.find("tmpl");
            if (tmpl_it == req.query_params.end()) return "No template";

            // Sanitize: strip expression markers from user template input
            std::string user_tmpl = tmpl_it->second;
            std::string sanitized;
            for (size_t i = 0; i < user_tmpl.size(); ++i) {
                if (i + 1 < user_tmpl.size() && user_tmpl[i] == '$' && user_tmpl[i+1] == '{') {
                    sanitized += "[";
                    ++i; // skip '{'
                } else if (user_tmpl[i] == '}') {
                    sanitized += "]";
                } else {
                    sanitized += user_tmpl[i];
                }
            }

            ResponseTemplate resp(sanitized);
            resp.bind_request(req);
            return resp.render();
        });
    }

    // Composite endpoint: fetches data then formats with user-chosen field
    std::future<std::string> handle_report(const RequestContext& req) {
        return std::async(std::launch::async, [this, req]() -> std::string {
            auto field_it = req.query_params.find("field");
            std::string field = (field_it != req.query_params.end()) ? field_it->second : "summary";

            // Simulated data store
            std::map<std::string, std::string> report_data = {
                {"summary", "Q4 Revenue Report"},
                {"author", "Finance Team"},
                {"status", "Published"}
            };

            // Validate field name - alphanumeric only
            bool valid_field = std::all_of(field.begin(), field.end(),
                [](char c) { return std::isalnum(c) || c == '_'; });

            if (!valid_field) return "Invalid field name";

            auto data_it = report_data.find(field);
            std::string value = (data_it != report_data.end()) ? data_it->second : "N/A";

            // The field name is used to construct the variable reference in template
            std::string tmpl = "Report ${data.field}: ${data.value}";
            ResponseTemplate resp(tmpl);
            resp.bind_request(req);
            resp.bind_data("data.field", field);
            resp.bind_data("data.value", value);
            return resp.render();
        });
    }

    // Batch processing endpoint
    std::future<std::string> handle_batch(const RequestContext& req) {
        return std::async(std::launch::async, [this, req]() -> std::string {
            auto items_it = req.query_params.find("items");
            if (items_it == req.query_params.end()) return "No items";

            // Parse comma-separated items
            std::string items_str = items_it->second;
            std::vector<std::string> items;
            std::stringstream ss(items_str);
            std::string item;
            while (std::getline(ss, item, ',')) {
                items.push_back(item);
            }

            // Process each item through template engine
            std::string result;
            for (size_t i = 0; i < items.size() && i < 10; ++i) {
                // Each item becomes a variable, then rendered in a fixed template
                std::string tmpl = "Item " + std::to_string(i) + ": ${data.current}\n";
                ResponseTemplate resp(tmpl);
                resp.bind_request(req);
                resp.bind_data("data.current", items[i]);
                result += resp.render();
            }
            return result;
        });
    }
};

int main() {
    AsyncHandler handler;

    // Simulate incoming requests
    RequestContext req1;
    req1.method = "GET";
    req1.path = "/greeting";
    req1.query_params["name"] = "alice";

    auto f1 = handler.handle_greeting(req1);
    std::cout << "Greeting: " << f1.get() << std::endl;

    RequestContext req2;
    req2.method = "GET";
    req2.path = "/batch";
    req2.query_params["items"] = "apple,${upper(param.items)},cherry";

    auto f2 = handler.handle_batch(req2);
    std::cout << "Batch: " << f2.get() << std::endl;

    return 0;
}
